import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 92 Asking for trouble","description":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 92 Asking for trouble","description":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 间接引语与视角转换，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 91 Three men in a basket","link":"/life/english/new-concept/book-2/unit-04/lesson-091"},"next":{"text":"第二册：实践与进步 · Lesson 93 A noble gift","link":"/life/english/new-concept/book-2/unit-04/lesson-093"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 91 Three men in a basket","link":"/life/english/new-concept/book-2/unit-04/lesson-091"},"next":{"text":"第二册：实践与进步 · Lesson 93 A noble gift","link":"/life/english/new-concept/book-2/unit-04/lesson-093"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-092.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-092.md"}'),i={name:"life/english/new-concept/book-2/unit-04/lesson-092.md"};function r(l,e,s,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-92-asking-for-trouble" tabindex="-1">第二册：实践与进步 · Lesson 92 Asking for trouble <a class="header-anchor" href="#第二册-实践与进步-·-lesson-92-asking-for-trouble" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 92 Asking for trouble&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>带讽刺的回应容易让本来简单的请求升级；练习否定转移和准确转述态度。本课的语言观察是：I do not think ... 常把否定放在 think 前，意义近于认为从句不成立；不能据此说每个 think 后的否定都必须前移。完成学习后，请写一次误会的处理，分开描述听到的语气、可能原因和自己的行动。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>sarcastic</td><td>/sɑːˈkæstɪk/</td><td>adj.</td><td>讽刺的</td><td>a sarcastic remark</td></tr><tr><td>tone</td><td>/təʊn/</td><td>n.</td><td>语气</td><td>a friendly tone</td></tr><tr><td>trouble</td><td>/ˈtrʌbəl/</td><td>n.</td><td>麻烦</td><td>avoid trouble</td></tr><tr><td>remark</td><td>/rɪˈmɑːk/</td><td>n.</td><td>评论；话语</td><td>a careless remark</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take offence — 感到被冒犯</li><li>in a calm tone — 用平静的语气</li></ul><h2 id="语法讲解-间接引语与视角转换" tabindex="-1">语法讲解：间接引语与视角转换 <a class="header-anchor" href="#语法讲解-间接引语与视角转换" aria-label="Permalink to &quot;语法讲解：间接引语与视角转换&quot;">​</a></h2><p>转述他人的话需要调整人称、时间和地点参照。主句为过去时且从过去视角回顾时，从句常相应后移时态；内容仍然有效或属于一般事实时，也可以保留现在时。陈述用 that 从句，是否问句用 if/whether，特殊疑问保留疑问词。转述疑问一律采用陈述语序，不保留原问句的助动词倒装；不能只换引号而不考虑说话视角。本课应用：I do not think ... 常把否定放在 think 前，意义近于认为从句不成立；不能据此说每个 think 后的否定都必须前移。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I do not think the receptionist meant to be rude.</p></blockquote><p>我认为接待员不是有意无礼。</p><p>do not think 否定判断，meant to be 表意图；说话者评价的是意图，而不是否认语气可能让人不舒服。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>rude 是形容词，rudely 是副词；meant to be 后用 rude，不是 rudely。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照 calm tone 与 sarcastic tone 的朗读，避免让文字相同的请求听起来像指责。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I do not think the receptionist meant to be rude. Her reply sounded sharp because the room was noisy. I repeated my question calmly and she helped me.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一次误会的处理，分开描述听到的语气、可能原因和自己的行动。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：do not think 否定判断，meant to be 表意图；说话者评价的是意图，而不是否认语气可能让人不舒服。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：rude 是形容词，rudely 是副词；meant to be 后用 rude，不是 rudely。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 rude/rudely：She did not mean to be ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> rude</p><p><strong>解析：</strong> be 后用形容词作表语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>说话者怎样重复问题？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Calmly.</p><p><strong>解析：</strong> 示范不支持他以讽刺回应。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“她粗鲁地回答”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She replied rudely.</p><p><strong>解析：</strong> 副词 rudely 修饰实义动词 replied。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：间接引语与视角转换。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-091">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-093">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",r]]);export{p as __pageData,b as default};
